# /login?err=<code> → kullanıcıya gösterilecek mesajın çeviri anahtarı (Cognito
# geri dönüş hatalarını güvenli, sabit bir kümeyle eşler; ham hata sızdırılmaz).
_AUTH_ERROR_KEYS = {
    "cognito": "auth.err_cognito",
    "link": "auth.err_link",
}

_RESET_USERNAME_KEY = "password_reset_username"
_RESET_STARTED_KEY = "password_reset_started_at"
_RESET_CONTEXT_MINUTES = 15
_FORGOT_GENERIC_KEY = "auth.forgot_generic"


@bp.route("/set-language", methods=["POST"])
@limiter.limit("30 per hour", key_func=get_remote_address)
def set_language():
    """Anonim/giriş-öncesi TR/EN seçimi. Dili session'a yazar; girişliyse
    hesaba da kalıcılaştırır. CSRF: durum-değiştiren POST → _csrf_protect korur.
    Hafif rate-limit: @login_required değil ve girişliyken DB'ye yazıyor; anonim
    kötüye kullanımı sınırla (2.2)."""
    data = request.get_json(silent=True) or {}
    lang = (data.get("lang") or "").strip().lower()
    if not set_locale(lang):
        return jsonify({"error": t("auth.set_lang_invalid")}), 400
    if current_user.is_authenticated:
        current_user.language = lang
        db.session.commit()
    else:
        # Giriş-öncesi AÇIK seçim işareti: _login_fresh bunu görürse seçimi
        # hesaba taşır. Bayraksız session['lang'] (örn. önceki kullanıcıdan
        # artakalan) hesabı ezmez.
        session["lang_explicit"] = True
    return jsonify({"ok": True, "language": lang})


def _cognito_available():
    return False


def _login_fresh(user):
    """Oturum sabitlemeye (session fixation) karşı: giriş ÖNCESI mevcut oturumu
    temizle, sonra login_user ile taze, kimliği bağlı bir oturum kur. Çerez içeriği
    değiştiği için saldırganın sabitlediği ön-giriş çerezi yeniden kullanılamaz."""
    # Giriş ekranında AÇIKÇA seçilen dil (set-language → lang_explicit) hesabın
    # kayıtlı tercihini günceller — aksi halde kullanıcının az önceki TR/EN
    # seçimi girişte sessizce eski tercihe dönüyordu. Bayraksız session['lang']
    # (önceki oturumdan artakalan) hesabı EZMEZ.
    explicit_lang = session.get("lang") if session.get("lang_explicit") else None
    session.clear()
    login_user(user)
    if explicit_lang in AVAILABLE_LOCALES and explicit_lang != getattr(user, "language", None):
        user.language = explicit_lang
        db.session.commit()
    # Oturum temizlendi → kullanıcının dil tercihini geri yükle (anon istek
    # akışında g.locale tutarlı kalsın; resolve_locale zaten user.language okur).
    if getattr(user, "language", None) in AVAILABLE_LOCALES:
        session["lang"] = user.language


def _login_username_key():
    """Per-account login rate-limit key: the submitted username (lowercased).

    The default login limit is keyed by client IP, which does not throttle a
    *distributed* brute force that spreads guesses for one account across many
    IPs. Keying a second limit on the username closes that gap. Combined with
    `deduct_when` (only failed logins count), a legitimate user who signs in
    successfully is never throttled. Tradeoff: an attacker can still burn a
    victim's failure budget to cause a short, self-healing lockout window — an
    accepted cost of any account-scoped throttle. Falls back to the client IP
    when no username is supplied."""
    data = request.get_json(silent=True) or {}
    uname = (data.get("username") or "").strip().lower()
    return f"login-user:{uname}" if uname else get_remote_address()


def _clear_reset_context():
    session.pop(_RESET_USERNAME_KEY, None)
    session.pop(_RESET_STARTED_KEY, None)


def _valid_reset_username():
    username = session.get(_RESET_USERNAME_KEY)
    started_at = session.get(_RESET_STARTED_KEY)
    try:
        age = time.time() - float(started_at)
    except (TypeError, ValueError):
        age = None
    if not username or age is None or age < 0 or age > timedelta(
            minutes=_RESET_CONTEXT_MINUTES).total_seconds():
        _clear_reset_context()
        return None
    return username


def _service_busy():
    """Saturated blocking capacity: retryable 503, never a crash (LP-01 idiom)."""
    response = jsonify({"error": t("auth.service_busy")})
    response.status_code = 503
    response.headers["Retry-After"] = "15"
    return response


def _reset_failure_response(failure):
    """Map a canonical recovery failure onto the pre-LP-02 browser answers.

    Pinned by tests/test_web_recovery_characterization.py: a local policy
    failure renders the validator sentence, a provider policy rejection its
    fixed sentence, a provider throttle 429, and every other provider answer
    the one "invalid or expired" sentence — including answers the native
    transport reports as unavailable, which the browser never distinguished.
    """
    outcome = failure.outcome
    if outcome == RecoveryOutcome.CAPACITY_EXHAUSTED:
        return _service_busy()
    if outcome == RecoveryOutcome.SESSIONS_NOT_REVOKED:
        return jsonify({"error": t("auth.reset_sessions_not_cleared")}), 503
    if outcome == RecoveryOutcome.FIELDS_REQUIRED:
        return jsonify({"error": t("auth.reset_fields_required")}), 400
    if outcome == RecoveryOutcome.PASSWORD_INVALID:
        if failure.phase == RecoveryPhase.VALIDATION:
            return jsonify({"error": failure.detail}), 400
        return jsonify({"error": t("auth.reset_password_rejected")}), 400
    if outcome == RecoveryOutcome.THROTTLED:
        return jsonify({"error": t("auth.reset_throttled")}), 429
    return jsonify({"error": t("auth.reset_invalid_or_expired")}), 400


@bp.route("/forgot-password", methods=["GET", "POST"])
@limiter.limit("5 per 15 minutes", key_func=get_remote_address, methods=["POST"])
def forgot_password():
    if request.method == "GET":
        return render_template("forgot_password.html")
    data = request.get_json(silent=True) or {}
    # Normalization, e-mail → username resolution, the provider call and the
    # non-enumeration rule live in the ONE recovery authority (shared with
    # native /api/v1/auth/password/forgot).
    try:
        requested = account_recovery.request_password_reset(
            data.get("identifier"))
    except RecoveryFailure as failure:
        if failure.outcome == RecoveryOutcome.CAPACITY_EXHAUSTED:
            return _service_busy()
        return jsonify({"error": t("auth.identifier_required")}), 400
    session[_RESET_USERNAME_KEY] = requested.identity
    session[_RESET_STARTED_KEY] = time.time()
    return jsonify({
        "message": t(_FORGOT_GENERIC_KEY),
        "next": url_for("auth.reset_password"),
    })


@bp.route("/reset-password", methods=["GET", "POST"])
@limiter.limit("10 per 15 minutes", key_func=get_remote_address, methods=["POST"])
def reset_password():
    username = _valid_reset_username()
    if not username:
        if request.method == "GET":
            flash(t("auth.reset_context_expired"), "error")
            return redirect(url_for("auth.forgot_password"))
        return jsonify({"error": t("auth.reset_context_expired")}), 409
    if request.method == "GET":
        return render_template("reset_password.html")
    data = request.get_json(silent=True) or {}
    code, password, confirmation = (
        data.get("code"), data.get("password"), data.get("confirm_password"))
    # The confirmation field is a browser form concern; the service validates
    # everything else (fields, canonical password policy, provider answer) and
    # revokes every session issued under the old credential.
    # Only the code is trimmed; a password is checked exactly as typed.
    if not (isinstance(code, str) and code.strip()
            and isinstance(password, str) and password
            and isinstance(confirmation, str) and confirmation):
        return jsonify({"error": t("auth.reset_fields_required")}), 400
    if password != confirmation:
        return jsonify({"error": t("auth.password_mismatch")}), 400
    try:
        account_recovery.reset_password(username, code, password)
    except RecoveryFailure as failure:
        return _reset_failure_response(failure)
    logout_user()
    session.clear()
    flash(t("auth.reset_success"), "success")
    return jsonify({
        "message": t("auth.reset_success"),
        "next": url_for("auth.login"),
    })


@bp.route("/register", methods=["GET","POST"])
@limiter.limit("5 per hour", key_func=get_remote_address, methods=["POST"])
def register():
    if request.method == "GET":
        return render_template("register.html", cognito_enabled=_cognito_available())
    if not COGNITO_ENABLED:
        return jsonify({"error": t("auth.login_unavailable")}), 503
    data = request.get_json(silent=True) or {}
    # Kayıt-öncesi seçilen dil: gövdeden gelir; yoksa session'daki seçime, o da
    # yoksa varsayılana düşer. Yeni kullanıcıya kalıcılaştırılır.
    chosen_lang = data.get("language")
    if chosen_lang not in AVAILABLE_LOCALES:
        chosen_lang = session.get("lang") if session.get("lang") in AVAILABLE_LOCALES else "tr"
    # Davet döngüsü: kayıt davet bağlantısından geldiyse (cookie veya body)
    # bekleyen davet olarak saklanır; ödül doğrulamada verilir.
    ref_code = data.get("ref") or request.cookies.get("fitx_ref")

    # Normalizasyon, doğrulama, çakışma kontrolü, Cognito kaydı ve yerel satır
    # TEK kanonik serviste (mobil /api/v1/auth/register ile ortak).
    try:
        account = account_registration.register_account(
            data.get("username"), data.get("email"), data.get("password"),
            language=chosen_lang, referral_code=ref_code)
    except RegistrationFailure as failure:
        return _registration_failure_response(
            failure, required_key="auth.all_fields_required")
    session["lang"] = chosen_lang
    resp = jsonify({"message": t("auth.register_verify_sent"),
                    "needs_verification": True, "username": account.username,
                    "referred": False})
    if request.cookies.get("fitx_ref"):
        resp.delete_cookie("fitx_ref")
    return resp


def _registration_failure_response(failure, required_key):
    """Map a canonical registration failure onto the pre-LP-01 browser answers.

    The browser contract is pinned by tests/test_web_registration_characterization.py:
    a provider rejection keeps rendering the provider's Turkish sentence (400),
    a local collision the one generic "taken" sentence, the post-sign-up commit
    race 409 and any other commit failure 503. Capacity exhaustion is the one
    answer that did not exist before: the provider call now runs inside the
    shared blocking slot, and a full slot is a retryable 503, never a crash.
    """
    outcome = failure.outcome
    if outcome == RegistrationOutcome.CAPACITY_EXHAUSTED:
        response = jsonify({"error": t("auth.service_busy")})
        response.status_code = 503
        response.headers["Retry-After"] = "15"
        return response
    if failure.provider_message is not None:
        return jsonify({"error": failure.provider_message}), 400
    if outcome == RegistrationOutcome.FIELDS_REQUIRED:
        return jsonify({"error": t(required_key)}), 400
    if outcome == RegistrationOutcome.IDENTITY_UNAVAILABLE:
        status = 409 if failure.phase == RegistrationPhase.PERSISTENCE else 400
        return jsonify({"error": t("auth.user_or_email_taken")}), status
    if outcome == RegistrationOutcome.STORAGE_FAILED:
        return jsonify({"error": t("auth.register_failed")}), 503
    return jsonify({"error": failure.detail}), 400


def _identity_deleted(sub):
    """LP-11: True — and this login's pending row write rolled back — when
    `DELETE /api/v1/account` removed this Cognito subject. Called after the
    subject is written onto the row and before commit, so a login that
    authenticated before the deletion cannot give the deleted identity a
    local account back (app/services/deleted_identity.py)."""
    try:
        deleted_identity.refuse_if_deleted(sub)
    except deleted_identity.IdentityDeleted:
        db.session.rollback()
        current_app.logger.warning("[LOGIN] identity_deleted: yerel kayıt "
                                   "geri oluşturulmadı")
        return True
    return False


def _reconcile_local_user(verified_claims, submitted_username):
    """H2: DOĞRULANMIŞ Cognito kimliğine karşılık gelen yerel kaydı bağla/oluştur.

    Neden var: /register önce Cognito'da kullanıcı yaratır, SONRA yerel satırı
    commit'ler. Aradaki commit düşerse (örn. aynı e-postayla yarışan iki kayıt →
    UNIQUE ihlali) Cognito'da hesap KALIR, yerelde satır YOKTUR = "orphan".
    Böyle bir kullanıcı geri dönüşsüz kilitlenirdi: yeniden kayıt Cognito'dan
    UsernameExists alır, giriş ise yerel satır bulunamadığı için 401'ler. UNSIGNED
    (public) app client admin-delete YAPAMAZ, yani uygulama Cognito tarafını
    temizleyemez de. Çözüm: girişte uzlaştır.

    Girdi, authenticate()'in DOĞRULAMASIZ decode'u değil, cognito_jwt.validate_token
    ile imzası/issuer/audience'ı sınanmış claim'lerdir — çağıran bunu garantiler.

    Yerel `username` = sağlayıcı kullanıcı adı (doğrulanmış `cognito:username`),
    ASLA giriş formuna yazılan tanımlayıcı değil: giriş e-posta takma adıyla ya
    da başka harf büyüklüğüyle yapılmış olabilir; o değer yazılırsa kurtarma bu
    satırı sağlayıcı kullanıcı adıyla bulamaz (docs/MOBILE_PASSWORD_RECOVERY.md §11).
    """
    sub = (verified_claims.get("sub") or "").strip()
    email = (verified_claims.get("email") or "").strip().lower()
    cognito_username = provider_username(verified_claims)
    if not sub or not email:
        return None

    # Güvenlik çıpası: e-posta Cognito tarafından DOĞRULANMIŞ olmalı. Cognito
    # email_verified'i ancak kullanıcı posta kutusuna gelen kodu girdikten sonra
    # true yapar. Bu kontrol olmadan, başkasının adresiyle kayıt olan biri o
    # adrese ait yerel hesabı kendine bağlayabilirdi.
    verified = verified_claims.get("email_verified")
    if verified is not True and str(verified).lower() != "true":
        current_app.logger.warning(
            "[LOGIN] orphan uzlaştırma reddedildi: email_verified değil (user=%s)",
            submitted_username)
        return None
    if cognito_username is None:
        current_app.logger.warning(
            "[LOGIN] orphan uzlaştırma reddedildi: doğrulanmış sağlayıcı "
            "kullanıcı adı yok (user=%s)", submitted_username)
        return None

    existing, denial = reconcilable_local_user(cognito_username, email, sub)
    if denial == "username_email_mismatch":
        current_app.logger.warning(
            "[LOGIN] orphan uzlaştırma reddedildi: kullanıcı adı doğrulanmış "
            "e-postayla eşleşmiyor (user=%s)", cognito_username)
        return None
    if denial == "subject_mismatch":
        current_app.logger.warning(
            "[LOGIN] orphan uzlaştırma atlandı: yerel kayıt başka bir sub'a "
            "bağlı (user=%s)", cognito_username)
        return None
    if denial is not None:
        # Every other denial (e.g. identity_ambiguous) refuses too: falling
        # through would create a new row beside the ones that matched.
        current_app.logger.warning(
            "[LOGIN] orphan uzlaştırma reddedildi: %s (user=%s)",
            denial, cognito_username)
        return None
    if existing is not None:
        existing.cognito_sub = sub
        if _identity_deleted(sub):
            return None
        db.session.commit()
        current_app.logger.info(
            "[LOGIN] Cognito orphan kurtarıldı: mevcut yerel kayıt bağlandı (user=%s)",
            cognito_username)
        return existing

    lang = session.get("lang") if session.get("lang") in AVAILABLE_LOCALES else "tr"
    user = User(username=cognito_username, email=email, cognito_sub=sub,
                full_name=(verified_claims.get("name") or cognito_username),
                language=lang)
    ensure_referral_code(user)
    db.session.add(user)
    try:
        if _identity_deleted(sub):
            return None
        db.session.commit()
    except IntegrityError:
        db.session.rollback()
        current_app.logger.error(
            "[LOGIN] orphan uzlaştırma başarısız: yerel kayıt oluşturulamadı "
            "(user=%s)", cognito_username)
        return None
    current_app.logger.info(
        "[LOGIN] Cognito orphan kurtarıldı: yerel kayıt oluşturuldu (user=%s)",
        cognito_username)
    return user


@bp.route("/login", methods=["GET","POST"])
@limiter.limit("10 per minute; 50 per hour", key_func=get_remote_address, methods=["POST"])
@limiter.limit("15 per 15 minutes", key_func=_login_username_key, methods=["POST"],
               deduct_when=lambda response: response.status_code == 401)
def login():
    if request.method == "GET":
        err_key = _AUTH_ERROR_KEYS.get(request.args.get("err", ""))
        auth_error = t(err_key) if err_key else None
        return render_template("login.html", cognito_enabled=_cognito_available(),
                               auth_error=auth_error)
    if not COGNITO_ENABLED:
        return jsonify({"error": t("auth.login_unavailable")}), 503
    # Fail-closed: Redis (dağıtık brute-force throttle) erişilemiyorsa login'i
    # reddet. Aksi halde limiter bellek-yedeğine düşer ve dağıtık deneme sayımı
    # zayıflar; saldırgan throttle'ı çok-süreçli ortamda aşabilir. Diğer route'lar
    # fail-open kalır (kullanılabilirlik tercihi).
    if current_app.config.get("LOGIN_FAIL_CLOSED", True) and not login_throttle_available():
        current_app.logger.warning(
            "[LOGIN] Redis erişilemiyor — login fail-closed (503), brute-force "
            "throttle güvenilir değil.")
        return jsonify({"error": t("auth.login_unavailable")}), 503
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""

    # L3: boş kimlik bilgisiyle Cognito'ya HİÇ gitme. Gizli app client
    # yapılandırılmışsa _secret_hash(None) ClientError DEĞİL TypeError yükseltir
    # → _wrap onu yakalayamaz ve temiz 401 yerine 500 döneriz. Ayrıca boş
    # kullanıcı adı zaten kimlik doğrulayamaz; erkenden reddet.
    if not username or not password:
        return jsonify({"error": t("auth.bad_credentials")}), 401

    # Cognito is the credential authority. Authenticate first; only a verified
    # ID-token sub may select the local application profile.
    if COGNITO_ENABLED:
        try:
            result = cognito_service.authenticate(username, password)
        except CognitoServiceError as e:
            # M7 (kabul edilen tradeoff): UserNotConfirmedException, "kayıtlı ama
            # doğrulanmamış" bir hesabı diğer hatalardan (generic bad_credentials,
            # 401) ayırt ettirir → dar bir hesap-sayım (enumeration) sinyali. Bunu
            # bilerek koruyoruz çünkü (a) doğrulanmamış kullanıcıyı /verify sayfasına
            # yönlendiren meşru UX buna bağlı, (b) Cognito app client'ında
            # PreventUserExistenceErrors AÇIK olduğunda bu istisna yalnızca parola
            # DOĞRUYKEN döner (yani ipucu zaten başarılı parola kontrolünün
            # arkasında), (c) per-username rate limit (15/15dk) kaba taramayı kısar.
            if e.code == "UserNotConfirmedException":
                return jsonify({"error": e.message, "needs_verification": True,
                                "username": username}), 403
            if e.code == "JWKSUnavailable":
                response = jsonify({"error": t("auth.temporarily_unavailable")})
                response.status_code = 503
                response.headers["Retry-After"] = "15"
                return response
            return jsonify({"error": e.message}), 401
        tokens = result["tokens"]
        # Kimlik token'ını KRİPTOGRAFİK olarak doğrula (JWKS) — claim'lere manuel
        # güvenme; imza/issuer/audience/exp Cognito JWKS'e karşı sınanır.
        # S4: sub karşılaştırması validate_token'ın DÖNDÜRDÜĞÜ (doğrulanmış)
        # claim'lerden yapılır — authenticate'in doğrulamasız decode'una
        # (result["claims"]) güvenilmez; bir refactor doğrulamayı sessizce
        # anlamsızlaştırmasın.
        try:
            verified_claims = cognito_jwt.validate_token(tokens["id_token"], "id")
        except TokenValidationError as e:
            # H1: JWKS'e ULAŞILAMADI ≠ imza GEÇERSİZ. Parola doğruydu; token'ı
            # doğrulayamamamızın nedeni bizim tarafımızdaki geçici bir kesinti.
            # Bunu "şifren yanlış" (401) diye raporlamak kullanıcıyı yanıltır ve
            # olayı gizler — geçici hata olarak 503 dön.
            if e.reason == "jwks_unavailable":
                resp = jsonify({"error": t("auth.temporarily_unavailable")})
                resp.status_code = 503
                resp.headers["Retry-After"] = "15"
                return resp
            return jsonify({"error": t("auth.bad_credentials")}), 401
        sub = (verified_claims.get("sub") or "").strip()
        user = User.query.filter_by(cognito_sub=sub).first() if sub else None
        if user is None:
            # H2: Cognito'da hesap var ama yerelde yok = ORPHAN (kayıt sırasında
            # sign_up başarılı olup yerel commit düştüğünde oluşur). Doğrulanmış
            # claim'lerden yerel kaydı bağla/oluştur — aksi halde kullanıcı kalıcı
            # olarak kilitlenir (yeniden kayıt UsernameExists alır, giriş 401'ler).
            user = _reconcile_local_user(verified_claims, username)
        if user is None:
            return jsonify({"error": t("auth.bad_credentials")}), 401
        if diverges_from_provider(user, verified_claims):
            current_app.logger.warning(
                "[LOGIN] identity_divergent user=%s", user.id)
        _login_fresh(user)
        # _login_fresh session.clear() yapar → cognito_sid'i SONRA yaz. Token'lar
        # sunucu tarafında şifreli saklanır; çerezde yalnızca opak session_id taşınır.
        session["cognito_sid"] = session_store.create(user, tokens, username)
        quest_result = complete_quest_for_user(user.id, "login")
        response = {"message": t("auth.welcome", username=user.username)}
        if quest_result:
            response["quest_awarded"] = quest_result
        return jsonify(response)


@bp.route("/verify", methods=["GET"])
def verify_page():
    """E-posta doğrulama sayfası. Native Cognito kaydı (veya doğrulanmamış giriş
    denemesi) sonrası kullanıcı buraya yönlendirilir; e-postasına gelen kodu girer."""
    if not COGNITO_ENABLED:
        abort(404)
    username = (request.args.get("u") or "").strip()
    return render_template("verify.html", username=username)


@bp.route("/verify", methods=["POST"])
@limiter.limit("10 per 15 minutes", key_func=get_remote_address, methods=["POST"])
def verify_confirm():
    """Kullanıcının girdiği doğrulama kodunu Cognito'da onayla."""
    if not COGNITO_ENABLED:
        abort(404)
    data = request.get_json(silent=True) or {}
    try:
        confirmed = account_registration.confirm_account(
            data.get("username"), data.get("code"))
    except RegistrationFailure as failure:
        return _registration_failure_response(
            failure, required_key="auth.verify_fields_required")
    return jsonify({"message": t("auth.verify_done"),
                    "referred": confirmed.referred})


@bp.route("/verify/resend", methods=["POST"])
@limiter.limit("3 per 15 minutes", key_func=get_remote_address, methods=["POST"])
def verify_resend():
    """Doğrulama kodunu yeniden gönder."""
    if not COGNITO_ENABLED:
        abort(404)
    data = request.get_json(silent=True) or {}
    try:
        account_registration.resend_confirmation(data.get("username"))
    except RegistrationFailure as failure:
        return _registration_failure_response(
            failure, required_key="auth.username_required")
    return jsonify({"message": t("auth.resend_done")})


def _revoke_local_sessions_for_global_logout(user_id):
    """End every locally-authoritative session this user already holds.

    Web logout calls Cognito GlobalSignOut, which invalidates every provider
    refresh token across devices. `authenticate_access` never consults Cognito
    — it validates the STORED provider access token offline — so a live
    `MobileAuthSession` family would keep authenticating after that global
    intent unless it is revoked here. Other browser `CognitoSession` rows are
    the same class of leftover: `require_auth` accepts the stored access token
    until refresh.

    Local revocation is the security-authoritative step and runs first. The
    credential-epoch fence is NOT used: logout is not a password change, and
    a later login with the still-valid password must succeed. The family sweep
    is the same primitive credential change uses.

    Returns (mobile_results, web_rows_deleted). Storage failure raises
    MobileAuthFailure for mobile, or a database exception for web rows; the
    caller must not claim logout completed.
    """
    mobile_results = mobile_auth.revoke_all_for_global_logout(user_id)
    web_deleted = session_store.delete_for_user(user_id)
    return mobile_results, web_deleted


@bp.route("/login/cognito")
def cognito_login():
    """Hosted UI is intentionally disabled for the native Cognito migration."""
    abort(404)


@bp.route("/auth/cognito/callback")
def cognito_callback():
    """Hosted UI callback is intentionally disabled for Sprint 1."""
    abort(404)

@bp.route("/logout")
@login_required
def logout():
    # Logout CSRF guard. The logout links across the app are same-site <a>
    # navigations (GET), so this can't be POST-only without reworking every
    # template. Instead, reject cross-site triggers — e.g. an attacker page
    # embedding <img src="/logout"> to silently sign the user out. A genuine
    # same-site navigation reports Sec-Fetch-Site: same-origin/same-site/none;
    # for older browsers without that header we fall back to a Referer check.
    sec_site = request.headers.get("Sec-Fetch-Site")
    if sec_site:
        if sec_site not in ("same-origin", "same-site", "none"):
            abort(403, description=t("route.csrf_failed"))
    else:
        # SEC-1: Sec-Fetch-Site yoksa Referer host'una düş. Referer DE yoksa
        # default-DENY — eskiden kontrol düşüp logout devam ediyordu, böylece
        # her iki başlığı da göndermeyen (legacy/non-browser) istemcilerde CSRF
        # ile sessiz sign-out mümkündü. Meşru same-site <a> gezintisi normalde
        # en az birini taşır.
        referer = request.headers.get("Referer")
        if not referer:
            abort(403, description=t("route.csrf_failed"))
        from urllib.parse import urlparse
        if urlparse(referer).hostname != request.host.split(":")[0]:
            abort(403, description=t("route.csrf_failed"))
    # Ordering (F5):
    #   1. Identity from Flask-Login only — never a client-supplied user_id.
    #   2. Capture the current access token for the later provider call.
    #   3. Revoke every local mobile family + delete every CognitoSession row.
    #      This is the security-authoritative step and must not depend on
    #      Cognito being reachable. Failure here aborts; the browser cookie
    #      stays so the user can retry. A 302 would claim global logout
    #      completed while locally-authoritative sessions might still live.
    #   4. Clear the Flask-Login cookie / session keys.
    #   5. Best-effort Cognito GlobalSignOut. A provider outage must not
    #      resurrect local sessions; it is logged, not rolled back.
    user_id = current_user.id
    sid = session.get("cognito_sid")
    access = None
    if sid:
        try:
            access = session_store.current_access_token(sid)
        except Exception:
            access = None
    try:
        mobile_results, web_deleted = _revoke_local_sessions_for_global_logout(
            user_id)
    except mobile_auth.MobileAuthFailure:
        current_app.logger.error(
            "[AUTH] global logout local sessions could not be revoked (user=%s)",
            user_id)
        abort(503)
    except Exception:
        current_app.logger.error(
            "[AUTH] global logout local sessions could not be revoked (user=%s)",
            user_id, exc_info=True)
        abort(503)
    session.pop("cognito_sid", None)
    session.pop("via_cognito", None)
    logout_user()
    if access:
        try:
            cognito_service.global_sign_out(access)
        except CognitoServiceError:
            current_app.logger.warning(
                "[AUTH] GlobalSignOut failed after local revoke (user=%s)",
                user_id)
    current_app.logger.info(
        "[AUTH] global logout completed (user=%s families=%d web_rows=%d)",
        user_id, len(mobile_results), web_deleted)
    return redirect(url_for("auth.login"))
